// AUTO-GENERATED from res/drawable-nodpi. Static when() so R8 keeps every referenced drawable.
// Key is "<route>_<themeKey>"; route==asset id for all tiles (See & Read uses the 'lens' route).

/** Per-theme home/tool ICON for a route, or 0 if none (caller falls back to the vector iconRes). */
@Composable fun themedIconRes(route: String): Int = themedIcon(route, activeThemeKey())

/** Per-theme home CARD art for a route, or 0 if none (caller falls back to cardRes/gradient). */
@Composable fun themedCardRes(route: String): Int = themedCard(route, activeThemeKey())

